@import url('https://fonts.googleapis.com/css2?family=Barlow+Condensed:wght@500;600;700;800;900&family=Rajdhani:wght@500;600;700&display=swap');
:root{color-scheme:dark;--cyan:#5bf4ed;--orange:#ff5b50;--ink:#111421;--font:'Barlow Condensed',Impact,sans-serif}*{box-sizing:border-box}html,body{margin:0;width:100%;height:100%;overflow:hidden;background:#0d1019;color:#fff;font-family:var(--font);user-select:none;-webkit-user-select:none}body{display:grid;place-items:center}.game-shell{position:relative;width:min(100vw,177.78vh);height:min(100vh,56.25vw);overflow:hidden;background:#141829;box-shadow:0 20px 90px #000b;isolation:isolate}canvas{display:block;width:100%;height:100%;touch-action:none}.hud{position:absolute;top:4.2%;left:5.25%;right:5.25%;display:grid;grid-template-columns:1fr 112px 1fr;gap:22px;align-items:start;pointer-events:none}.fighter-card{min-width:0}.name-row{display:flex;align-items:center;justify-content:space-between;margin:0 0 7px;text-shadow:0 2px 6px #000}.name{font-size:clamp(20px,3vw,34px);font-weight:900;letter-spacing:2px;line-height:1}.role{font:700 clamp(8px,1vw,12px) Rajdhani,sans-serif;letter-spacing:1.5px;color:#d4d7e3;white-space:nowrap}.right-card .role{margin-right:auto}.right-card .name{margin-left:14px}.health-track{position:relative;height:clamp(15px,2.1vw,24px);background:#181b28;border:2px solid #e8e9f4;box-shadow:0 3px 12px #0009;transform:skewX(-10deg);overflow:hidden}.health-fill{height:100%;width:100%;transition:width .18s ease;position:relative}.aoi-fill{background:linear-gradient(180deg,#7cfff4,#16b8c5 63%,#16828f)}.haggar-fill{margin-left:auto;background:linear-gradient(180deg,#ff9a67,#f04e4e 63%,#a62d48)}.health-sheen{position:absolute;inset:2px 0 auto;height:2px;background:#fff8}.meter-track{height:5px;margin-top:5px;background:#252837;overflow:hidden}.meter-fill{height:100%;width:0;background:linear-gradient(90deg,#73fff6,#38b9fd);transition:width .2s}.enemy-meter{margin-left:auto;background:linear-gradient(90deg,#ffb15e,#ff615f)}.stat-line{display:flex;justify-content:space-between;margin-top:4px;color:#b9bdcc;font:700 10px Rajdhani,sans-serif;letter-spacing:1px}.center-hud{text-align:center;position:relative;padding-top:1px}.round-label{color:#c3c6d3;font:700 10px Rajdhani,sans-serif;letter-spacing:2px}.timer{font-size:clamp(28px,4.2vw,48px);font-weight:900;line-height:.95;text-shadow:0 3px 12px #000}.round-call{position:absolute;top:82px;left:50%;transform:translateX(-50%);white-space:nowrap;color:#fff;font-size:clamp(15px,2.4vw,27px);font-weight:900;font-style:italic;letter-spacing:1px;text-shadow:0 2px 14px #000,0 0 18px #ff5b75;opacity:0;transition:opacity .25s}.round-call.show{opacity:1}.top-right{position:absolute;right:5.3%;top:1.7%;font:700 10px Rajdhani,sans-serif;letter-spacing:1.8px;color:#d0d2df;display:flex;align-items:center;gap:7px}.live-dot{height:6px;width:6px;border-radius:100%;background:#ff655f;box-shadow:0 0 9px #ff655f}#sound-toggle{pointer-events:auto;background:none;border:1px solid #ffffff3a;color:#fff;border-radius:5px;height:24px;width:27px;font-size:15px;cursor:pointer;margin-left:5px}.bottom-hint{position:absolute;bottom:2.6%;left:5.3%;right:5.3%;display:flex;justify-content:space-between;color:#c6c8d2;font:600 10px Rajdhani,sans-serif;letter-spacing:1.3px;text-shadow:0 2px 5px #000;pointer-events:none}.bottom-hint b{font-size:11px;color:#fff;border:1px solid #ffffff69;border-radius:3px;padding:2px 5px;background:#141a2aab}.hint-right{color:#9298aa}.hint-right i{font-style:normal;color:var(--cyan);margin-left:6px}.message{position:absolute;inset:0;z-index:5;display:flex;flex-direction:column;align-items:center;justify-content:center;background:#090c18a8;backdrop-filter:blur(4px)}.message.hidden{display:none}#message-title{font-size:clamp(60px,13vw,132px);font-weight:900;font-style:italic;letter-spacing:4px;color:#fff;text-shadow:0 4px 0 #e13d5c,0 0 35px #ff375e;line-height:1}#message-sub{font-size:clamp(22px,4vw,42px);font-weight:900;letter-spacing:4px;margin:6px 0 24px;color:var(--cyan);text-shadow:0 0 20px #44e8ed}#rematch{font-family:var(--font);font-weight:800;letter-spacing:2px;font-size:16px;background:linear-gradient(100deg,#49e7dc,#2489d2);color:#0e1722;border:0;padding:12px 26px;cursor:pointer;clip-path:polygon(8% 0,100% 0,92% 100%,0 100%);box-shadow:0 6px 25px #28d9dd55}.touch-controls{display:none;position:absolute;inset:auto 0 9%;justify-content:space-between;align-items:end;padding:0 5%;pointer-events:none;touch-action:none}.move-pad,.action-pad{position:relative;height:124px;width:142px;pointer-events:auto}.touch-button{position:absolute;border:1px solid #ffffff55;color:#fff;background:#121b2cbb;backdrop-filter:blur(5px);font:800 12px var(--font);letter-spacing:1px;touch-action:none;box-shadow:0 3px 10px #0008}.move-pad .touch-button{width:42px;height:42px;border-radius:12px;font-size:17px}.move-pad .up{left:50px;top:0}.move-pad .left{left:4px;top:43px}.move-pad .down{left:50px;top:43px}.move-pad .right{left:96px;top:43px}.action-pad{width:164px}.action-pad .touch-button{height:44px;border-radius:50%;width:60px}.action-pad .punch{right:74px;top:34px;background:#157c8ccc}.action-pad .kick{right:5px;top:5px;background:#ab3e55cc}.action-pad .special{right:3px;top:72px;width:66px;background:#7543b8cc}.action-pad .block{right:76px;top:78px;background:#27314ccc}.touch-button.active{filter:brightness(1.7);transform:scale(.94)}.mobile-hint{display:none}@media(max-width:700px),(pointer:coarse){.touch-controls{display:flex}.bottom-hint{bottom:2%;font-size:9px}.desktop-hint{display:none}.mobile-hint{display:inline}.hud{left:3%;right:3%;top:5%;gap:8px;grid-template-columns:1fr 52px 1fr}.name{font-size:clamp(17px,5vw,25px)}.role{font-size:7px;letter-spacing:.7px}.name-row{margin-bottom:5px}.health-track{height:15px}.stat-line{font-size:8px}.round-label{font-size:8px}.timer{font-size:29px}.round-call{top:54px}.top-right{top:1.5%;right:3%;font-size:8px}.center-hud{padding-top:3px}}
@media(max-height:500px){.touch-controls{bottom:7%;transform:scale(.8);transform-origin:bottom}.bottom-hint{bottom:1.4%}.hud{top:3.3%}}

(() => {
  'use strict';
  const canvas = document.getElementById('game');
  const ctx = canvas.getContext('2d');
  const W = 1280, H = 720;
  let dpr = 1, last = 0, elapsed = 0, shake = 0, ended = false, paused = false, muted = false;
  const keys = new Set(), particles = [], texts = [];
  const ui = {
    aoi: document.getElementById('health-aoi'), haggar: document.getElementById('health-haggar'),
    meterA: document.getElementById('meter-aoi'), meterH: document.getElementById('meter-haggar'),
    timer: document.getElementById('timer'), msg: document.getElementById('message'), title: document.getElementById('message-title'),
    sub: document.getElementById('message-sub'), call: document.getElementById('round-call'), statusA: document.getElementById('status-aoi'), statusH: document.getElementById('status-haggar')
  };
  const game = { time: 99, intro: 2.4, hitstop: 0, flash: 0, aiThink: .3 };
  function fighter(name, x, health, maxHealth, style) {
    return { name, x, z: 0, y: 0, vx: 0, vy: 0, health, maxHealth, meter: 0, style, facing: name === 'aoi' ? 1 : -1,
      attack: null, cooldown: 0, stun: 0, blocking: false, hurtFlash: 0, anim: Math.random() * 5, walking: false, invuln: 0 };
  }
  const aoi = fighter('aoi', 425, 800, 800, 'aoi');
  const haggar = fighter('haggar', 855, 1500, 1500, 'haggar');
  function resize() {
    const rect = canvas.getBoundingClientRect(); dpr = Math.min(2, window.devicePixelRatio || 1);
    canvas.width = Math.round(rect.width * dpr); canvas.height = Math.round(rect.height * dpr);
  }
  window.addEventListener('resize', resize); resize();
  const clamp = (v, a, b) => Math.max(a, Math.min(b, v));
  const rand = (a, b) => a + Math.random() * (b - a);
  function ellipse(x,y,rx,ry,fill,stroke,sw=1) { ctx.beginPath();ctx.ellipse(x,y,rx,ry,0,0,Math.PI*2);ctx.fillStyle=fill;ctx.fill();if(stroke){ctx.lineWidth=sw;ctx.strokeStyle=stroke;ctx.stroke();} }
  function path(points, fill, stroke='#151724', sw=3) { ctx.beginPath();ctx.moveTo(points[0][0],points[0][1]);for(let i=1;i<points.length;i++)ctx.lineTo(points[i][0],points[i][1]);ctx.closePath();ctx.fillStyle=fill;ctx.fill();if(stroke){ctx.lineWidth=sw;ctx.strokeStyle=stroke;ctx.lineJoin='round';ctx.stroke();} }
  function line(points,color,width=6) { ctx.beginPath();ctx.moveTo(points[0][0],points[0][1]);for(let i=1;i<points.length;i++)ctx.lineTo(points[i][0],points[i][1]);ctx.strokeStyle=color;ctx.lineWidth=width;ctx.lineCap='round';ctx.lineJoin='round';ctx.stroke(); }
  function gradient(y1,y2,stops){const g=ctx.createLinearGradient(0,y1,0,y2);for(const [p,c] of stops)g.addColorStop(p,c);return g;}
  function drawBackground(t) {
    const sky=ctx.createLinearGradient(0,0,0,570);sky.addColorStop(0,'#11172d');sky.addColorStop(.52,'#493149');sky.addColorStop(1,'#e56754');ctx.fillStyle=sky;ctx.fillRect(0,0,W,H);
    // dusk glow and distant moon
    const glow=ctx.createRadialGradient(640,320,10,640,320,370);glow.addColorStop(0,'#ffb16e55');glow.addColorStop(1,'#ffb16e00');ctx.fillStyle=glow;ctx.fillRect(250,40,780,560);
    ellipse(925,168,45,45,'#ffd7a5cc');ellipse(909,157,48,47,'#4e3655');
    // skyline silhouette
    const buildings=[[0,345,90,220],[78,300,104,260],[170,365,85,195],[238,276,114,284],[336,340,86,220],[405,255,140,305],[534,350,84,210],[602,292,106,268],[700,330,96,230],[776,245,125,315],[894,323,100,237],[976,286,112,274],[1078,347,90,213],[1150,265,130,295]];
    for(let i=0;i<buildings.length;i++){const [x,y,w,h]=buildings[i];ctx.fillStyle=i%2?'#27253a':'#30283b';ctx.fillRect(x,y,w,h);ctx.fillStyle='#ffae6848';for(let yy=y+22;yy<540;yy+=27)for(let xx=x+13;xx<x+w-8;xx+=25){if(((xx+yy+i*7)%4)<2)ctx.fillRect(xx,yy,7,10);}}
    // signs / distant neon
    ctx.save();ctx.globalAlpha=.6;ctx.shadowBlur=15;ctx.shadowColor='#fb578c';ctx.fillStyle='#ff769b';ctx.fillRect(268,329,72,8);ctx.fillStyle='#61e7ed';ctx.shadowColor='#61e7ed';ctx.fillRect(850,302,51,7);ctx.restore();
    // crowd silhouettes
    ctx.fillStyle='#171725';ctx.fillRect(0,470,1280,92);
    for(let i=0;i<52;i++){const x=i*25+(i%3)*3;const headY=randStable(i,480,500);ellipse(x,headY,7,8,'#171725');ctx.fillStyle=i%7===0?'#42314a':'#1c1b2b';ctx.beginPath();ctx.moveTo(x-12,headY+8);ctx.lineTo(x-17,550);ctx.lineTo(x+17,550);ctx.lineTo(x+11,headY+8);ctx.fill();}
    // arena rear barricade
    const rail=ctx.createLinearGradient(0,500,0,577);rail.addColorStop(0,'#373044');rail.addColorStop(.4,'#1c2030');rail.addColorStop(1,'#101521');ctx.fillStyle=rail;ctx.fillRect(0,508,1280,71);ctx.fillStyle='#f47768';ctx.fillRect(0,505,1280,5);ctx.fillStyle='#293342';ctx.fillRect(0,547,1280,4);
    // floor perspective
    const floor=ctx.createLinearGradient(0,566,0,720);floor.addColorStop(0,'#342b36');floor.addColorStop(.35,'#252531');floor.addColorStop(1,'#111824');ctx.fillStyle=floor;ctx.beginPath();ctx.moveTo(0,565);ctx.lineTo(1280,565);ctx.lineTo(1280,720);ctx.lineTo(0,720);ctx.fill();
    ctx.strokeStyle='#e99a7650';ctx.lineWidth=2;for(let i=-6;i<=6;i++){ctx.beginPath();ctx.moveTo(640+i*44,565);ctx.lineTo(640+i*145,720);ctx.stroke();}for(let y=590;y<730;y+=34){ctx.beginPath();ctx.moveTo(0,y);ctx.lineTo(1280,y);ctx.stroke();}
    // floor edge and light pools
    const pool=ctx.createRadialGradient(640,590,10,640,590,450);pool.addColorStop(0,'#f8aa7242');pool.addColorStop(1,'#f8aa7200');ctx.fillStyle=pool;ctx.fillRect(100,480,1080,240);
    ctx.fillStyle='#f4b77a';ctx.shadowColor='#ff8055';ctx.shadowBlur=20;ctx.fillRect(0,565,1280,2);ctx.shadowBlur=0;
  }
  function randStable(seed,a,b){const x=Math.sin(seed*127.1+11.7)*43758.5453;return a+(x-Math.floor(x))*(b-a);}
  function drawLeg(f, front, pose, time) {
    const dark=f.style==='aoi'?'#155469':'#55382f', main=f.style==='aoi'?'#27a9b5':'#d68a5b', outline='#171724';
    const sway=Math.sin(time*8+(front?0:1))*2;
    let hip=[front?1:-8, -51], knee=[front?7:-13,-29], foot=[front?17:-21+sway,-5];
    if(pose==='walk'){const phase=Math.sin(time*11+(front?0:Math.PI));knee=[(front?3:-8)+phase*11,-29+Math.abs(phase)*3];foot=[(front?12:-16)+phase*17,-4+Math.max(0,-phase)*5];}
    if(pose==='kick'&&f.attack&&f.attack.kind==='kick'&&front){knee=[39,-44];foot=[69,-53];}
    if(pose==='special'&&f.attack&&front){knee=[11,-37];foot=[26,-12];}
    line([hip,knee,foot],outline,17);line([hip,knee,foot],main,12);line([hip[0],hip[1]-1,knee[0],knee[1]-1],dark,3);
    ellipse(foot[0]+5,foot[1]+1,13,6,f.style==='aoi'?'#182b3c':'#29222a',outline,2);
    if(f.style==='aoi'){ellipse(knee[0],knee[1],5,5,'#66d8dc');}
  }
  function drawFighter(f, t) {
    const depthScale=1-f.z*.055;const ground=552+f.z*46-f.y;const walk=f.walking&&!f.attack&&!f.stun?'walk':'idle';
    const bob=(walk==='idle'&&!f.attack?Math.sin(t*3+f.anim)*1.5:Math.sin(t*12+f.anim)*2);
    const kind=f.attack?.kind;
    ctx.save();ctx.translate(f.x,ground+bob);ctx.scale(depthScale,depthScale);ctx.globalAlpha=f.invuln>0&&Math.floor(t*22)%2===0?.45:1;
    // long soft shadow
    ctx.save();ctx.globalAlpha=.35;ellipse(0,0,45+Math.abs(f.y)*.13,12,'#090d18');ctx.restore();
    // fighters face the opponent; local +x is forward
    ctx.scale(f.facing,1);
    const hitColor=f.hurtFlash>0;
    ctx.save();ctx.translate(0,-f.y*.04);
    drawLeg(f,false,walk,t);drawLeg(f,true,walk,t);
    // hips and torso silhouette
    if(f.style==='aoi'){
      path([[-18,-57],[-22,-73],[-15,-87],[10,-90],[21,-77],[16,-54],[8,-45],[-13,-46]],hitColor?'#ffe9ed':'#177f94','#102334',3);
      path([[-15,-83],[-9,-89],[12,-85],[16,-72],[-9,-68]],hitColor?'#fff':'#46d8d1','#133040',2);
      // short jacket tails
      path([[-15,-76],[-27,-62],[-34,-42],[-24,-47],[-8,-62]],'#16869a','#123047',2);
      path([[5,-74],[17,-64],[25,-46],[16,-51],[3,-63]],'#1cb2b8','#123047',2);
      // scarf
      path([[-11,-85],[-20,-92],[-35,-88],[-24,-82],[-12,-81]],'#f6f1dc','#29354a',2);
      path([[-23,-87],[-38,-88],[-46,-77],[-30,-81]],'#e35e68','#752d48',2);
    } else {
      path([[-22,-58],[-24,-76],[-17,-91],[16,-91],[24,-76],[21,-55],[11,-44],[-14,-45]],hitColor?'#ffe9ed':'#b77a53','#32262d',4);
      path([[-19,-87],[-15,-94],[12,-92],[19,-83],[13,-73],[-13,-73]],'#e4b274','#392b2c',2);
      // chest and belt
      line([[-10,-86],[1,-74],[13,-85]],'#f1c38a',3);path([[-19,-57],[-18,-63],[18,-63],[20,-55],[0,-50]],'#e5d7bd','#40302e',2);ellipse(0,-58,4,4,'#b7673c','#67402f',1);
      // tank-top straps
      path([[-18,-90],[-12,-91],[-5,-76],[-11,-75]],'#eee0ca','#594137',1);path([[8,-91],[16,-90],[10,-75],[4,-76]],'#eee0ca','#594137',1);
    }
    drawArms(f,t,kind,hitColor);
    drawHead(f,t,hitColor);
    // contact aura / special glow
    if(kind==='special'&&f.attack){ctx.save();ctx.globalCompositeOperation='lighter';const pulse=.7+Math.sin(t*25)*.2;const g=ctx.createRadialGradient(26,-64,2,26,-64,80*pulse);g.addColorStop(0,f.style==='aoi'?'#9fffffcc':'#ffc17dcc');g.addColorStop(.3,f.style==='aoi'?'#31e9ed88':'#ff684f88');g.addColorStop(1,'#fff0');ctx.fillStyle=g;ctx.beginPath();ctx.arc(26,-64,80*pulse,0,Math.PI*2);ctx.fill();ctx.restore();}
    if(f.blocking){ctx.strokeStyle=f.style==='aoi'?'#8effff99':'#ffd89b99';ctx.lineWidth=4;ctx.beginPath();ctx.arc(0,-68,37,-1.3,1.3);ctx.stroke();}
    ctx.restore();ctx.restore();
  }
  function drawArms(f,t,kind,hitColor){
    const aoiStyle=f.style==='aoi', skin=hitColor?'#ffe8ec':aoiStyle?'#edc0a3':'#e5ad79', sleeve=aoiStyle?'#1596a8':'#d1a878', outline=aoiStyle?'#102638':'#3c2929';
    const frontShoulder=[12,-82], rearShoulder=[-13,-82];
    // rear arm at guard, or counter-swing
    let rEl=[-24,-71],rHand=[-14,-62],fEl=[28,-69],fHand=[18,-57];
    if(f.blocking){rEl=[-25,-65];rHand=[-16,-80];fEl=[21,-60];fHand=[25,-82];}
    if(kind==='punch'&&f.attack){fEl=[30,-83];fHand=[61,-82];}
    if(kind==='kick'&&f.attack){fEl=[23,-65];fHand=[28,-56];}
    if(kind==='special'&&f.attack){fEl=[41,-74];fHand=[58,-70];}
    if(f.stun>0){rEl=[-28,-71];rHand=[-26,-59];fEl=[29,-72];fHand=[31,-60];}
    for(const [shoulder,el,hand,front] of [[rearShoulder,rEl,rHand,false],[frontShoulder,fEl,fHand,true]]){
      line([shoulder,el,hand],outline,17);line([shoulder,el,hand],front?sleeve:(aoiStyle?'#176178':'#996344'),12);line([[shoulder[0],shoulder[1]+1],[el[0],el[1]+1]],skin,5);ellipse(hand[0],hand[1],aoiStyle?8:10,8,skin,outline,2);
      if(aoiStyle&&front)line([[shoulder[0]+1,shoulder[1]+3],[el[0],el[1]-2]],'#82f4e3',2);
      if(kind==='punch'&&front&&f.attack){ellipse(hand[0]+5,hand[1],10,8,aoiStyle?'#edc0a3':'#e5ad79',outline,2);}
    }
  }
  function drawHead(f,t,hitColor){
    const aoiStyle=f.style==='aoi', skin=hitColor?'#ffe9ed':aoiStyle?'#f0c3a9':'#e8b17c', outline=aoiStyle?'#122437':'#39282b';
    const headX=aoiStyle?1:1, headY=-105+(f.stun?Math.sin(t*24)*2:0);
    // neck
    path([[-7,-87],[8,-88],[9,-98],[-7,-98]],skin,outline,2);
    ellipse(headX,headY,16,19,skin,outline,3);
    if(aoiStyle){
      // sweeping dark hair, bright streaks
      path([[-15,-108],[-12,-124],[0,-130],[15,-123],[22,-111],[10,-116],[2,-111],[-3,-119],[-8,-108],[-18,-101]],'#172238','#0e1728',2);
      path([[-11,-117],[-2,-127],[4,-127],[-3,-115]],'#4ecdd0',null);
      path([[5,-123],[15,-119],[20,-111],[11,-115]],'#e95c83',null);
      // ear / eye / brows
      ellipse(14,-104,3,5,skin,'#b87c79',1);line([[5,-108],[12,-109]],'#21283b',2);line([[7,-104],[12,-104]],'#192337',2);
      path([[-4,-96],[2,-93],[8,-96]],'#b96571',null);
      // headband tails
      path([[-9,-117],[-19,-114],[-26,-104],[-17,-110]],'#ed617c','#7d3457',1);
    } else {
      // heavy swept-back hair and beard
      path([[-17,-111],[-15,-126],[-5,-133],[10,-130],[19,-120],[18,-111],[8,-116],[-2,-115],[-11,-108]],'#42302e','#28212a',2);
      path([[-16,-100],[-9,-95],[0,-97],[10,-94],[15,-101],[12,-91],[4,-87],[-8,-89],[-15,-94]],'#654538','#39282b',2);
      line([[3,-107],[11,-106]],'#2a2527',2);line([[5,-102],[10,-102]],'#221e25',2);
      line([[-6,-111],[5,-111]],'#493432',3);
    }
    // shine
    ellipse(-7,-109,3,2,'#fff8');
  }

const moves = {
  aoi: { punch:{startup:.11,active:.15,total:.39,damage:150,range:105,knock:185,meter:13}, kick:{startup:.19,active:.17,total:.55,damage:205,range:132,knock:245,meter:17}, special:{startup:.34,active:.22,total:.82,damage:310,range:250,knock:330,meter:0,cost:55} },
  haggar: { punch:{startup:.24,active:.20,total:.68,damage:120,range:104,knock:160,meter:12}, kick:{startup:.42,active:.19,total:.91,damage:180,range:135,knock:235,meter:16}, special:{startup:.62,active:.23,total:1.28,damage:260,range:155,knock:375,meter:0,cost:45} }
};
function startAttack(f, kind) {
  if(ended||game.intro>0||f.stun>0||f.attack||f.cooldown>0)return;
  const move=moves[f.name][kind];if(move.cost&&f.meter<move.cost)return;
  if(move.cost)f.meter-=move.cost;
  f.blocking=false;f.attack={kind,age:0,hit:false,move};f.cooldown=move.total*.3;
  if(kind==='special')burst(f);
}
function burst(f){
  for(let i=0;i<22;i++){const ang=rand(-Math.PI,Math.PI),speed=rand(45,260);particles.push({x:f.x+f.facing*32,y:500+f.z*46-80,vx:Math.cos(ang)*speed,vy:Math.sin(ang)*speed-30,life:rand(.22,.6),max:.6,color:f.style==='aoi'?(Math.random()<.5?'#69fff1':'#50aaff'):(Math.random()<.5?'#ffbd70':'#ff5164'),size:rand(2,7)});}
  game.flash=.14;
}
function hit(attacker, target, move) {
  if(attacker.attack.hit||target.invuln>0)return;
  const dx=target.x-attacker.x, dz=Math.abs(target.z-attacker.z);
  if(Math.abs(dx)>move.range || dz>.9)return;
  // Facing and vertical evasion are meaningful; specials still travel at jump height.
  if(dx*attacker.facing< -20)return;
  attacker.attack.hit=true;
  let damage=move.damage;
  if(target.blocking){damage=Math.max(12,Math.round(damage*(target.style==='haggar'?.23:.34)));target.stun=.16;target.meter=Math.min(100,target.meter+8);spark(target,true);floatText(target.x,groundY(target)-112,'GUARD', '#c5f8ff');}
  else {target.health=Math.max(0,target.health-damage);target.stun=attacker.style==='haggar'?.47:.35;target.hurtFlash=.18;target.vx=attacker.facing*move.knock;target.vy=target.y>30?230:0;target.invuln=.22;attacker.meter=Math.min(100,attacker.meter+move.meter);spark(target,false);floatText(target.x,groundY(target)-105,`-${damage}`,target.style==='aoi'?'#ffdfaa':'#fff');shake=attacker.style==='haggar'?9:6;game.hitstop=.075;}
  target.health=Math.max(0,target.health-damage); // block damage is intentionally chip damage
  playHit(target.blocking);
  if(target.health<=0)finish(attacker);
}
function groundY(f){return 552+f.z*46-f.y;}
function spark(f,guard){
  const x=f.x+f.facing*-24,y=groundY(f)-76;
  for(let i=0;i<15;i++){const a=rand(0,Math.PI*2),speed=rand(45,270);particles.push({x,y,vx:Math.cos(a)*speed,vy:Math.sin(a)*speed-35,life:rand(.18,.48),max:.48,color:guard?'#8afaff':(f.style==='aoi'?'#ffb8a2':'#fff1c8'),size:rand(2,6)});}
}
function floatText(x,y,text,color){texts.push({x,y,text,color,life:.8});}
function finish(winner){if(ended)return;ended=true;ui.title.textContent='K.O.';ui.sub.textContent=`${winner.name.toUpperCase()} WINS!`;ui.msg.classList.remove('hidden');playHit(false);}
let audioCtx=null;
function playHit(guard){if(muted)return;try{audioCtx??=new (window.AudioContext||window.webkitAudioContext)();const osc=audioCtx.createOscillator(),gain=audioCtx.createGain();osc.type=guard?'sine':'triangle';osc.frequency.setValueAtTime(guard?520:115,audioCtx.currentTime);osc.frequency.exponentialRampToValueAtTime(guard?210:48,audioCtx.currentTime+.11);gain.gain.setValueAtTime(.11,audioCtx.currentTime);gain.gain.exponentialRampToValueAtTime(.001,audioCtx.currentTime+.13);osc.connect(gain);gain.connect(audioCtx.destination);osc.start();osc.stop(audioCtx.currentTime+.14);}catch(e){}}
function updateFighter(f,dt){
  f.anim+=dt;f.cooldown=Math.max(0,f.cooldown-dt);f.stun=Math.max(0,f.stun-dt);f.hurtFlash=Math.max(0,f.hurtFlash-dt);f.invuln=Math.max(0,f.invuln-dt);
  f.facing=(f===aoi?(haggar.x>=aoi.x?1:-1):(aoi.x>=haggar.x?1:-1));
  if(f.attack){f.attack.age+=dt;const m=f.attack.move;if(!f.attack.hit&&f.attack.age>=m.startup&&f.attack.age<=m.startup+m.active)hit(f,f===aoi?haggar:aoi,m);if(f.attack.age>=m.total)f.attack=null;}
  f.x+=f.vx*dt;f.vx*=Math.pow(.001,dt);f.y+=f.vy*dt;f.vy-=1500*dt;if(f.y<0){f.y=0;f.vy=0;}f.x=clamp(f.x,120,1160);
}
function updateAI(dt){
  if(game.intro>0||ended||haggar.stun>0)return;
  const distance=Math.abs(aoi.x-haggar.x), toward=aoi.x>haggar.x?1:-1;
  haggar.walking=false;haggar.blocking=false;
  // Read the player's wind-up and brace against an incoming strike.
  if(aoi.attack&&aoi.attack.age<aoi.attack.move.startup*.95&&distance<150&&Math.random()<.73){haggar.blocking=true;return;}
  game.aiThink-=dt;if(game.aiThink>0)return;game.aiThink=rand(.18,.43);
  if(distance>155){haggar.vx=toward*100;haggar.walking=true;}
  else if(distance<88){haggar.vx=-toward*42;}
  else haggar.vx*=.3;
  if(distance<153&&haggar.cooldown<=0&&!haggar.attack){
    const roll=Math.random();if(haggar.meter>=45&&distance<130&&roll<.20)startAttack(haggar,'special');else if(roll<.43)startAttack(haggar,'kick');else startAttack(haggar,'punch');
  }
  if(Math.random()<.04&&distance>100)haggar.z=clamp(haggar.z+rand(-.5,.5),-.7,.7);
}
function update(dt){
  if(paused)return;
  if(game.hitstop>0){game.hitstop-=dt;return;}
  elapsed+=dt;game.intro=Math.max(0,game.intro-dt);if(game.intro<1.6&&game.intro>0)ui.call.classList.add('show');else ui.call.classList.remove('show');
  if(!ended&&game.intro<=0){game.time=Math.max(0,game.time-dt);if(game.time===0)finish(aoi.health>=haggar.health?aoi:haggar);}
  if(game.flash>0)game.flash-=dt;
  updateAI(dt);
  if(game.intro<=0&&!ended){
    aoi.walking=false;aoi.blocking=keys.has('shift');
    if(aoi.stun<=0&&!aoi.attack){const speed=aoi.blocking?145:255;let mx=(keys.has('d')?1:0)-(keys.has('a')?1:0),mz=(keys.has('s')?1:0)-(keys.has('w')?1:0);if(mx&&mz){mx*=.707;mz*=.707;}aoi.vx=mx*speed;aoi.z=clamp(aoi.z+mz*dt*1.35,-.75,.75);aoi.walking=!!(mx||mz);if(keys.has(' ')&&aoi.y===0){aoi.vy=560;keys.delete(' ');}}
    if(aoi.blocking)aoi.vx*=.84;
  }
  updateFighter(aoi,dt);updateFighter(haggar,dt);
  // Keep fighters from passing through one another; attacks can still cross up by jumping/depth.
  if(Math.abs(aoi.z-haggar.z)<.55&&Math.abs(aoi.x-haggar.x)<48){const sign=aoi.x<haggar.x?-1:1;const overlap=48-Math.abs(aoi.x-haggar.x);aoi.x+=sign*overlap*.5;haggar.x-=sign*overlap*.5;}
  for(let i=particles.length-1;i>=0;i--){const p=particles[i];p.life-=dt;p.x+=p.vx*dt;p.y+=p.vy*dt;p.vx*=Math.pow(.08,dt);p.vy-=420*dt;if(p.life<=0)particles.splice(i,1);}
  for(let i=texts.length-1;i>=0;i--){texts[i].life-=dt;texts[i].y-=35*dt;if(texts[i].life<=0)texts.splice(i,1);}
  shake=Math.max(0,shake-dt*28);
  syncUI();
}
function syncUI(){ui.aoi.style.width=`${aoi.health/aoi.maxHealth*100}%`;ui.haggar.style.width=`${haggar.health/haggar.maxHealth*100}%`;ui.meterA.style.width=`${aoi.meter}%`;ui.meterH.style.width=`${haggar.meter}%`;ui.timer.textContent=String(Math.ceil(game.time)).padStart(2,'0');ui.statusA.textContent=aoi.stun>0?'STUNNED':aoi.meter>=55?'BURST READY':aoi.blocking?'GUARDING':'READY';ui.statusH.textContent=haggar.stun>0?'STUNNED':haggar.meter>=45?'POWER READY':'READY';}

