content.text:
@import url('https://fonts.googleapis.com/css2?family=Barlow+Condensed:wght@500;600;700;800;900&family=Rajdhani:wght@500;600;700&display=swap');
:root{color-scheme:dark;--cyan:#5bf4ed;--orange:#ff5b50;--ink:#111421;--font:'Barlow Condensed',Impact,sans-serif}
*{box-sizing:border-box}
html,body{margin:0;width:100%;height:100%;overflow:hidden;background:#0d1019;color:#fff;font-family:var(--font);user-select:none;-webkit-user-select:none}
body{display:grid;place-items:center}
.game-shell{position:relative;width:min(100vw,177.78vh);height:min(100vh,56.25vw);overflow:hidden;background:#141829;box-shadow:0 20px 90px #000b;isolation:isolate}
canvas{display:block;width:100%;height:100%;touch-action:none}
.hud{position:absolute;top:4.2%;left:5.25%;right:5.25%;display:grid;grid-template-columns:1fr 112px 1fr;gap:22px;align-items:start;pointer-events:none}
.fighter-card{min-width:0}
.name-row{display:flex;align-items:center;justify-content:space-between;margin:0 0 7px;text-shadow:0 2px 6px #000}
.name{font-size:clamp(20px,3vw,34px);font-weight:900;letter-spacing:2px;line-height:1}
.role{font:700 clamp(8px,1vw,12px) Rajdhani,sans-serif;letter-spacing:1.5px;color:#d4d7e3;white-space:nowrap}
.right-card .role{margin-right:auto}
.right-card .name{margin-left:14px}
.health-track{position:relative;height:clamp(15px,2.1vw,24px);background:#181b28;border:2px solid #e8e9f4;box-shadow:0 3px 12px #0009;transform:skewX(-10deg);overflow:hidden}
.health-fill{height:100%;width:100%;transition:width .18s ease;position:relative}
.aoi-fill{background:linear-gradient(180deg,#7cfff4,#16b8c5 63%,#16828f)}
.haggar-fill{margin-left:auto;background:linear-gradient(180deg,#ff9a67,#f04e4e 63%,#a62d48)}
.health-sheen{position:absolute;inset:2px 0 auto;height:2px;background:#fff8}
.meter-track{height:5px;margin-top:5px;background:#252837;overflow:hidden}
.meter-fill{height:100%;width:0;background:linear-gradient(90deg,#73fff6,#38b9fd);transition:width .2s}
.enemy-meter{margin-left:auto;background:linear-gradient(90deg,#ffb15e,#ff615f)}
.stat-line{display:flex;justify-content:space-between;margin-top:4px;color:#b9bdcc;font:700 10px Rajdhani,sans-serif;letter-spacing:1px}
.center-hud{text-align:center;position:relative;padding-top:1px}
.round-label{color:#c3c6d3;font:700 10px Rajdhani,sans-serif;letter-spacing:2px}
.timer{font-size:clamp(28px,4.2vw,48px);font-weight:900;line-height:.95;text-shadow:0 3px 12px #000}
.round-call{position:absolute;top:82px;left:50%;transform:translateX(-50%);white-space:nowrap;color:#fff;font-size:clamp(15px,2.4vw,27px);font-weight:900;font-style:italic;letter-spacing:1px;text-shadow:0 2px 14px #000,0 0 18px #ff5b75;opacity:0;transition:opacity .25s}
.round-call.show{opacity:1}
.top-right{position:absolute;right:5.3%;top:1.7%;font:700 10px Rajdhani,sans-serif;letter-spacing:1.8px;color:#d0d2df;display:flex;align-items:center;gap:7px}
.live-dot{height:6px;width:6px;border-radius:100%;background:#ff655f;box-shadow:0 0 9px #ff655f}
#sound-toggle{pointer-events:auto;background:none;border:1px solid #ffffff3a;color:#fff;border-radius:5px;height:24px;width:27px;font-size:15px;cursor:pointer;margin-left:5px}
.bottom-hint{position:absolute;bottom:2.6%;left:5.3%;right:5.3%;display:flex;justify-content:space-between;color:#c6c8d2;font:600 10px Rajdhani,sans-serif;letter-spacing:1.3px;text-shadow:0 2px 5px #000;pointer-events:none}
.bottom-hint b{font-size:11px;color:#fff;border:1px solid #ffffff69;border-radius:3px;padding:2px 5px;background:#141a2aab}
.hint-right{color:#9298aa}
.hint-right i{font-style:normal;color:var(--cyan);margin-left:6px}
.message{position:absolute;inset:0;z-index:5;display:flex;flex-direction:column;align-items:center;justify-content:center;background:#090c18a8;backdrop-filter:blur(4px)}
.message.hidden{display:none}
#message-title{font-size:clamp(60px,13vw,132px);font-weight:900;font-style:italic;letter-spacing:4px;color:#fff;text-shadow:0 4px 0 #e13d5c,0 0 35px #ff375e;line-height:1}
#message-sub{font-size:clamp(22px,4vw,42px);font-weight:900;letter-spacing:4px;margin:6px 0 24px;color:var(--cyan);text-shadow:0 0 20px #44e8ed}
#rematch{font-family:var(--font);font-weight:800;letter-spacing:2px;font-size:16px;background:linear-gradient(100deg,#49e7dc,#2489d2);color:#0e1722;border:0;padding:12px 26px;cursor:pointer;clip-path:polygon(8% 0,100% 0,92% 100%,0 100%);box-shadow:0 6px 25px #28d9dd55}
.touch-controls{display:none;position:absolute;inset:auto 0 9%;justify-content:space-between;align-items:end;padding:0 5%;pointer-events:none;touch-action:none}
.move-pad,.action-pad{position:relative;height:124px;width:142px;pointer-events:auto}
.touch-button{position:absolute;border:1px solid #ffffff55;color:#fff;background:#121b2cbb;backdrop-filter:blur(5px);font:800 12px var(--font);letter-spacing:1px;touch-action:none;box-shadow:0 3px 10px #0008}
.move-pad .touch-button{width:42px;height:42px;border-radius:12px;font-size:17px}
.move-pad .up{left:50px;top:0}
.move-pad .left{left:4px;top:43px}
.move-pad .down{left:50px;top:43px}
.move-pad .right{left:96px;top:43px}
.action-pad{width:164px}
.action-pad .touch-button{height:44px;border-radius:50%;width:60px}
.action-pad .punch{right:74px;top:34px;background:#157c8ccc}
.action-pad .kick{right:5px;top:5px;background:#ab3e55cc}
.action-pad .special{right:3px;top:72px;width:66px;background:#7543b8cc}
.action-pad .block{right:76px;top:78px;background:#27314ccc}
.touch-button.active{filter:brightness(1.7);transform:scale(.94)}
.mobile-hint{display:none}
@media(max-width:700px),(pointer:coarse){.touch-controls{display:flex}
.bottom-hint{bottom:2%;font-size:9px}
.desktop-hint{display:none}
.mobile-hint{display:inline}
.hud{left:3%;right:3%;top:5%;gap:8px;grid-template-columns:1fr 52px 1fr}
.name{font-size:clamp(17px,5vw,25px)}
.role{font-size:7px;letter-spacing:.7px}
.name-row{margin-bottom:5px}
.health-track{height:15px}
.stat-line{font-size:8px}
.round-label{font-size:8px}
.timer{font-size:29px}
.round-call{top:54px}
.top-right{top:1.5%;right:3%;font-size:8px}
.center-hud{padding-top:3px}
}

@media(max-height:500px){.touch-controls{bottom:7%;transform:scale(.8);transform-origin:bottom}
.bottom-hint{bottom:1.4%}
.hud{top:3.3%}
}

